using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public static class ListExtensions
{
	public static T PickRandom<T>(this IList<T> list, bool seeded = true)
	{
		if (seeded)
		{
			return list[RandomUtilities.RandomIntWithSeed(list.Count)];
		}
		return list[RandomUtilities.RandomInt(list.Count)];
	}

	public static List<T> PickRandom<T>(this List<T> list, int count, bool seeded = true)
	{
		int count2 = list.Count;
		if (count2 == 0)
		{
			return new List<T>();
		}
		if (count > count2)
		{
			count = count2;
		}
		List<T> list2 = list.Duplicate();
		List<T> list3 = new List<T>();
		for (int i = 0; i < count; i++)
		{
			list3.Add(list2.PopRandom(seeded));
		}
		return list3;
	}

	public static List<T> PickRandomCanPickMoreThanOnce<T>(this List<T> list, int count, bool seeded = true)
	{
		int count2 = list.Count;
		if (count2 == 0)
		{
			return new List<T>();
		}
		if (count > count2)
		{
			count = count2;
		}
		List<T> list2 = list.Duplicate();
		List<T> list3 = new List<T>();
		for (int i = 0; i < count; i++)
		{
			list3.Add(list2.PickRandom(seeded));
		}
		return list3;
	}

	public static T PopRandom<T>(this IList<T> list, bool seeded = true)
	{
		int index = ((!seeded) ? RandomUtilities.RandomInt(list.Count) : RandomUtilities.RandomIntWithSeed(list.Count));
		T result = list[index];
		list.RemoveAt(index);
		return result;
	}

	public static List<T> PopRandom<T>(this IList<T> list, int amount, bool seeded = true)
	{
		List<T> list2 = new List<T>();
		for (int i = 0; i < amount; i++)
		{
			list2.Add(list.PopRandom(seeded));
		}
		return list2;
	}

	public static T First<T>(this IList<T> list)
	{
		return list[0];
	}

	public static T Last<T>(this IList<T> list)
	{
		return list[list.Count - 1];
	}

	public static T PopFirst<T>(this IList<T> list)
	{
		T result = list.First();
		list.RemoveAt(0);
		return result;
	}

	public static T PopLast<T>(this IList<T> list)
	{
		T result = list.Last();
		list.RemoveAt(list.Count - 1);
		return result;
	}

	public static T Pop<T>(this IList<T> list, int index)
	{
		if (list.Count <= index)
		{
			return default(T);
		}
		T result = list[index];
		list.RemoveAt(index);
		return result;
	}

	public static void RemoveNullObjects<T>(this List<T> list)
	{
		list.RemoveAll((T item) => item?.Equals(null) ?? true);
	}

	public static void Shuffle<T>(this IList<T> list, bool seeded = true)
	{
		for (int num = list.Count - 1; num > 1; num--)
		{
			int index = ((!seeded) ? RandomUtilities.RandomInt(num + 1) : RandomUtilities.RandomIntWithSeed(num + 1));
			T value = list[index];
			list[index] = list[num];
			list[num] = value;
		}
	}

	public static List<T> Duplicate<T>(this List<T> list)
	{
		List<T> list2 = new List<T>();
		for (int i = 0; i < list.Count; i++)
		{
			list2.Add(list[i]);
		}
		return list2;
	}

	public static void SwitchPlaces<T>(this IList<T> list, int indexOne, int indexTwo)
	{
		if (indexOne >= 0 && indexTwo >= 0 && indexOne != indexTwo && indexOne < list.Count && indexTwo < list.Count)
		{
			T value = list[indexOne];
			list[indexOne] = list[indexTwo];
			list[indexTwo] = value;
		}
	}

	public static void MoveElementFromIndexToIndex<T>(this List<T> list, int fromIndex, int desiredIndex)
	{
		desiredIndex = Mathf.Clamp(desiredIndex, 0, list.Count - 1);
		T value = list[desiredIndex];
		list[desiredIndex] = list[fromIndex];
		list[fromIndex] = value;
	}

	public static void AddIfNotAlreadyOnList<T>(this IList<T> list, T item)
	{
		if (!list.Contains(item))
		{
			list.Add(item);
		}
	}

	public static void AddItemsIfNotAlreadyOnList<T>(this IList<T> list, IList<T> items)
	{
		for (int i = 0; i < items.Count; i++)
		{
			if (!list.Contains(items[i]))
			{
				list.Add(items[i]);
			}
		}
	}

	public static List<int> MakeAnIndexList(this List<int> list, int listSize)
	{
		for (int i = 0; i < listSize; i++)
		{
			list.Add(i);
		}
		return list;
	}

	public static void InteractThroughItems<T>(this IList<T> list, Action<T> action)
	{
		for (int i = 0; i < list.Count; i++)
		{
			action?.Invoke(list[i]);
		}
	}

	public static IEnumerator ActionBetweenItems<T>(this IList<T> list, float timeBetweenItems, Action<int> action)
	{
		for (int i = 0; i < list.Count; i++)
		{
			action?.Invoke(i);
			yield return new WaitForSeconds(timeBetweenItems);
		}
	}

	public static IEnumerator ActionBetweenItems<T>(this IList<T> list, bool shuffleBetweenCycles, int cycles, float timeBetweenItems, Action<int, int> action)
	{
		for (int i = 0; i < cycles; i++)
		{
			if (shuffleBetweenCycles)
			{
				list.Shuffle();
			}
			for (int j = 0; j < list.Count; j++)
			{
				action?.Invoke(i, j);
				yield return new WaitForSeconds(timeBetweenItems);
			}
		}
	}

	public static IEnumerator ActionBetweenItemsIncreasingTime<T>(this IList<T> list, bool shuffleBetweenCycles, int cycles, float timeBetweenItems, int startIncreasingDurationThreshold, float timeBetweenItemsIncrease, Action<int, int> action)
	{
		int counter = 0;
		int interactionsCount = cycles * list.Count;
		for (int i = 0; i < cycles; i++)
		{
			if (shuffleBetweenCycles)
			{
				list.Shuffle();
			}
			for (int j = 0; j < list.Count; j++)
			{
				action?.Invoke(i, j);
				yield return new WaitForSeconds(timeBetweenItems);
				counter++;
				if (counter >= interactionsCount - startIncreasingDurationThreshold)
				{
					timeBetweenItems += timeBetweenItemsIncrease;
				}
			}
		}
	}

	public static float GetTimeUntillTheEndOfListInteraction<T>(this IList<T> list, int cycles, float timeBetweenItems)
	{
		return (float)(cycles * list.Count) * timeBetweenItems;
	}

	public static float GetTimeUntillTheEndOfListInteraction<T>(this IList<T> list, int cycles, float timeBetweenItems, float startIncreasingDurationThreshold, float timeBetweenItemsIncrease)
	{
		float num = (float)(cycles * list.Count) * timeBetweenItems;
		for (int i = 0; (float)i < startIncreasingDurationThreshold; i++)
		{
			num += timeBetweenItemsIncrease * (float)(i + 1);
		}
		return num;
	}
}
